CREATE TABLE IF NOT EXISTS app_lock (id INTEGER PRIMARY KEY) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS users (
 id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(100) NOT NULL, username VARCHAR(80) NOT NULL UNIQUE,
 email VARCHAR(160) NOT NULL UNIQUE, phone VARCHAR(30) NOT NULL, password_hash VARCHAR(255) NOT NULL,
 role VARCHAR(20) NOT NULL, active INTEGER NOT NULL DEFAULT 1, specialty VARCHAR(200) NOT NULL DEFAULT '',
 created_at VARCHAR(30) NOT NULL
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS sessions (token VARCHAR(64) PRIMARY KEY, user_id BIGINT NOT NULL, expires_at VARCHAR(30) NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS services (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(100) NOT NULL, description VARCHAR(500) NOT NULL, price INTEGER NOT NULL, duration INTEGER NOT NULL, active INTEGER NOT NULL DEFAULT 1, image INTEGER NOT NULL DEFAULT 0) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS appointments (
 id BIGINT PRIMARY KEY AUTO_INCREMENT, client_id BIGINT, guest_name VARCHAR(100) NOT NULL DEFAULT '', guest_phone VARCHAR(30) NOT NULL DEFAULT '',
 professional_id BIGINT NOT NULL, service_id BIGINT NOT NULL, date VARCHAR(10) NOT NULL, time VARCHAR(5) NOT NULL,
 duration INTEGER NOT NULL, price INTEGER NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'Pendiente',
 design VARCHAR(80) NOT NULL DEFAULT '', color VARCHAR(40) NOT NULL DEFAULT '', notes VARCHAR(1000) NOT NULL DEFAULT '', reason VARCHAR(500) NOT NULL DEFAULT '', created_at VARCHAR(30) NOT NULL,
 FOREIGN KEY(client_id) REFERENCES users(id), FOREIGN KEY(professional_id) REFERENCES users(id), FOREIGN KEY(service_id) REFERENCES services(id)
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS payments (id BIGINT PRIMARY KEY AUTO_INCREMENT, appointment_id BIGINT NOT NULL UNIQUE, amount INTEGER NOT NULL, method VARCHAR(30) NOT NULL, status VARCHAR(20) NOT NULL, date VARCHAR(10) NOT NULL, FOREIGN KEY(appointment_id) REFERENCES appointments(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS products (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(100) NOT NULL, category VARCHAR(80) NOT NULL, stock INTEGER NOT NULL DEFAULT 0, minimum INTEGER NOT NULL DEFAULT 5, active INTEGER NOT NULL DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS stock_movements (id BIGINT PRIMARY KEY AUTO_INCREMENT, product_id BIGINT NOT NULL, quantity INTEGER NOT NULL, reason VARCHAR(200) NOT NULL, user_id BIGINT NOT NULL, created_at VARCHAR(30) NOT NULL, FOREIGN KEY(product_id) REFERENCES products(id), FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS availability (id BIGINT PRIMARY KEY AUTO_INCREMENT, user_id BIGINT NOT NULL, date VARCHAR(10) NOT NULL, start_time VARCHAR(5) NOT NULL, end_time VARCHAR(5) NOT NULL, reason VARCHAR(200) NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS settings (id INTEGER PRIMARY KEY, name VARCHAR(100) NOT NULL, phone VARCHAR(30) NOT NULL, email VARCHAR(160) NOT NULL, address VARCHAR(200) NOT NULL, cancellation_hours INTEGER NOT NULL, lead_hours INTEGER NOT NULL, lead_minutes INTEGER, opens VARCHAR(5) NOT NULL, closes VARCHAR(5) NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS notifications (id BIGINT PRIMARY KEY AUTO_INCREMENT, user_id BIGINT NOT NULL, appointment_id BIGINT NOT NULL, message VARCHAR(500) NOT NULL, created_at VARCHAR(30) NOT NULL, read_at VARCHAR(30), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(appointment_id) REFERENCES appointments(id)) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS professional_supplies (id BIGINT PRIMARY KEY AUTO_INCREMENT, product_id BIGINT NOT NULL, professional_id BIGINT NOT NULL, quantity INTEGER NOT NULL, unit_cost DECIMAL(12,2) NOT NULL DEFAULT 0, started_at VARCHAR(30) NOT NULL, exhausted_at VARCHAR(30) NOT NULL DEFAULT '', FOREIGN KEY(product_id) REFERENCES products(id), FOREIGN KEY(professional_id) REFERENCES users(id)) ENGINE=InnoDB;
